LOCAL void mouse_callback_push IFN1(word, value)
{
    setSP(getSP() - 2);
    sas_storew(effective_addr(getSS(), getSP()), value);
}

LOCAL word mouse_callback_pop IFN0()
{
    word value;
    sas_loadw(effective_addr(getSS(), getSP()), &value);
    setSP(getSP() + 2);
    return value;
}

